CREATE OR REPLACE FUNCTION public.conferir_metodo_acesso()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE alvo uuid;
BEGIN
  IF TG_TABLE_NAME = 'usuarios' THEN
    alvo := COALESCE(NEW.id, OLD.id);
  ELSE
    alvo := OLD.usuario_id;
  END IF;
  PERFORM id FROM usuarios WHERE id = alvo FOR UPDATE;
  IF EXISTS (SELECT 1 FROM usuarios u WHERE u.id = alvo AND u.senha_hash IS NULL
      AND NOT EXISTS (SELECT 1 FROM identidades_google g WHERE g.usuario_id = u.id)) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Conta exige um método de acesso';
  END IF;
  RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION public.preservar_identidade_membro()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.usuario_id <> OLD.usuario_id OR NEW.republica_id <> OLD.republica_id THEN
    RAISE EXCEPTION 'O vínculo não pode mudar de usuário ou república; desative-o e crie outro' USING ERRCODE = 'RH001';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.serializar_administracao()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  PERFORM pg_advisory_xact_lock(20261014, 1);
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.sincronizar_pagamento()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE despesa_alvo uuid; total numeric;
BEGIN
  SELECT sum(valor) INTO total FROM pagamentos WHERE rateio_id = NEW.rateio_id;
  UPDATE rateios_despesa SET valor_pago = total,
    status = CASE WHEN total = valor_devido THEN 'PAGO'::"StatusRateio" ELSE 'PARCIAL'::"StatusRateio" END
    WHERE id = NEW.rateio_id RETURNING despesa_id INTO despesa_alvo;
  UPDATE despesas SET status = CASE WHEN EXISTS (
    SELECT 1 FROM rateios_despesa WHERE despesa_id = despesa_alvo AND status <> 'PAGO'
  ) THEN 'PENDENTE'::"StatusDespesa" ELSE 'PAGA'::"StatusDespesa" END WHERE id = despesa_alvo;
  RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.validar_administradores()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF EXISTS (
    SELECT 1 FROM republicas r
    JOIN usuarios u ON u.id = r.admin_id
    WHERE u.tipo_usuario NOT IN ('USUARIO_ADMIN', 'USUARIO_MASTER')
       OR NOT EXISTS (
         SELECT 1 FROM membros_republica m
         WHERE m.usuario_id = r.admin_id AND m.republica_id = r.id AND m.ativo
       )
  ) THEN
    RAISE EXCEPTION 'O administrador deve ter perfil ADMIN/MASTER e vínculo ativo na república' USING ERRCODE = 'RH001';
  END IF;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.validar_despesa()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.republica_id <> OLD.republica_id THEN
      RAISE EXCEPTION 'Uma despesa não pode mudar de república' USING ERRCODE = 'RH001';
    END IF;
    IF NEW.valor_total <> OLD.valor_total AND EXISTS (
      SELECT 1 FROM pagamentos p JOIN rateios_despesa rd ON rd.id = p.rateio_id
      WHERE rd.despesa_id = OLD.id
    ) THEN
      RAISE EXCEPTION 'Uma despesa com pagamento não pode ter seu valor alterado' USING ERRCODE = 'RH001';
    END IF;
  END IF;
  IF TG_OP = 'INSERT' OR NEW.criada_por_id IS DISTINCT FROM OLD.criada_por_id THEN
    IF NOT EXISTS (
      SELECT 1 FROM usuarios u JOIN republicas r ON r.id = NEW.republica_id
      WHERE u.id = NEW.criada_por_id AND u.ativo AND r.ativa
        AND (u.tipo_usuario = 'USUARIO_MASTER' OR
          (u.tipo_usuario = 'USUARIO_ADMIN' AND r.admin_id = u.id AND EXISTS (
            SELECT 1 FROM membros_republica m
            WHERE m.usuario_id = u.id AND m.republica_id = r.id AND m.ativo
          )))
    ) THEN
      RAISE EXCEPTION 'A despesa exige administrador da própria república ou MASTER ativo' USING ERRCODE = 'RH001';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validar_financeiro()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE alvo uuid; valor_despesa numeric; estado "StatusDespesa";
  total numeric; menor numeric; maior numeric; quantidade integer; pendentes integer;
BEGIN
  IF TG_TABLE_NAME = 'despesas' THEN alvo := NEW.id;
  ELSIF TG_OP = 'DELETE' THEN alvo := OLD.despesa_id; ELSE alvo := NEW.despesa_id; END IF;
  SELECT valor_total, status INTO valor_despesa, estado FROM despesas WHERE id = alvo;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT coalesce(sum(valor_devido), 0), min(valor_devido), max(valor_devido), count(*),
    count(*) FILTER (WHERE status <> 'PAGO') INTO total, menor, maior, quantidade, pendentes
    FROM rateios_despesa WHERE despesa_id = alvo;
  IF quantidade = 0 OR total <> valor_despesa OR maior - menor > 0.01 THEN
    RAISE EXCEPTION 'Os rateios devem dividir igualmente e somar exatamente o total da despesa' USING ERRCODE = 'RH001';
  END IF;
  -- Agregar por rateio evita duplicar valores devidos quando há vários pagamentos.
  IF EXISTS (SELECT 1 FROM rateios_despesa r WHERE r.despesa_id = alvo
    AND r.valor_pago <> (SELECT coalesce(sum(p.valor),0) FROM pagamentos p WHERE p.rateio_id = r.id)) THEN
    RAISE EXCEPTION 'O valor pago deve corresponder à soma dos pagamentos registrados' USING ERRCODE = 'RH001';
  END IF;
  IF (estado = 'PAGA') <> (pendentes = 0) THEN
    RAISE EXCEPTION 'O status da despesa deve refletir a quitação de todos os rateios' USING ERRCODE = 'RH001';
  END IF;
  RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.validar_pagamento()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE rateio rateios_despesa%ROWTYPE; despesa_alvo uuid;
BEGIN
  SELECT despesa_id INTO despesa_alvo FROM rateios_despesa WHERE id = NEW.rateio_id;
  -- Mesma ordem de locks para todos os pagamentos: despesa, depois rateio.
  PERFORM 1 FROM despesas WHERE id = despesa_alvo FOR UPDATE;
  SELECT * INTO rateio FROM rateios_despesa WHERE id = NEW.rateio_id FOR UPDATE;
  IF NOT FOUND OR rateio.membro_id <> NEW.membro_id THEN
    RAISE EXCEPTION 'O pagamento deve pertencer ao membro do rateio' USING ERRCODE = 'RH001';
  END IF;
  IF NEW.valor <= 0 OR NEW.valor > rateio.valor_devido - rateio.valor_pago THEN
    RAISE EXCEPTION 'O pagamento ultrapassa o saldo pendente do rateio' USING ERRCODE = 'RH001';
  END IF;
  RETURN NEW;
END; $function$

CREATE OR REPLACE FUNCTION public.validar_rateio()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  despesa_alvo uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN despesa_alvo := OLD.despesa_id;
  ELSE despesa_alvo := NEW.despesa_id;
  END IF;
  -- A mesma despesa serializa novos rateios, ajustes e pagamentos concorrentes.
  PERFORM 1 FROM despesas WHERE id = despesa_alvo FOR UPDATE;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW.despesa_id <> OLD.despesa_id OR NEW.membro_id <> OLD.membro_id THEN
      RAISE EXCEPTION 'Um rateio não pode mudar de despesa ou membro' USING ERRCODE = 'RH001';
    END IF;
    IF NEW.valor_devido <> OLD.valor_devido AND EXISTS (
      SELECT 1 FROM pagamentos p JOIN rateios_despesa rd ON rd.id = p.rateio_id
      WHERE rd.despesa_id = despesa_alvo
    ) THEN
      RAISE EXCEPTION 'Não é permitido alterar rateios de uma despesa com pagamento' USING ERRCODE = 'RH001';
    END IF;
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NOT EXISTS (
      SELECT 1 FROM membros_republica m
      JOIN despesas d ON d.republica_id = m.republica_id
      JOIN usuarios u ON u.id = m.usuario_id
      JOIN republicas r ON r.id = m.republica_id
      WHERE m.id = NEW.membro_id AND d.id = NEW.despesa_id AND m.ativo AND u.ativo AND r.ativa
    ) THEN
      RAISE EXCEPTION 'O membro do rateio deve estar ativo e pertencer à república da despesa' USING ERRCODE = 'RH001';
    END IF;
    IF EXISTS (
      SELECT 1 FROM pagamentos p JOIN rateios_despesa rd ON rd.id = p.rateio_id
      WHERE rd.despesa_id = despesa_alvo
    ) THEN
      RAISE EXCEPTION 'Não é permitido incluir rateios após o primeiro pagamento' USING ERRCODE = 'RH001';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validar_responsavel_tarefa()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT' OR NEW.responsavel_id IS DISTINCT FROM OLD.responsavel_id
    OR NEW.republica_id IS DISTINCT FROM OLD.republica_id THEN
    IF NOT EXISTS (
      SELECT 1 FROM membros_republica m JOIN usuarios u ON u.id = m.usuario_id
      JOIN republicas r ON r.id = m.republica_id
      WHERE m.id = NEW.responsavel_id AND m.republica_id = NEW.republica_id
        AND m.ativo AND u.ativo AND r.ativa
    ) THEN
      RAISE EXCEPTION 'O responsável da tarefa deve estar ativo na mesma república' USING ERRCODE = 'RH001';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validar_selecao_recorrencia()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE alvo uuid; quantidade integer; valor numeric;
BEGIN
  IF TG_TABLE_NAME='configuracoes_recorrencia' THEN alvo:=NEW.id; ELSE alvo:=NEW.configuracao_id; END IF;
  SELECT c.valor_total,count(p.membro_id) INTO valor,quantidade FROM configuracoes_recorrencia c
    LEFT JOIN recorrencias_participantes p ON p.configuracao_id=c.id WHERE c.id=alvo GROUP BY c.valor_total;
  IF quantidade=0 OR valor < quantidade * 0.01 THEN
    RAISE EXCEPTION 'Seleção deve permitir rateio igualitário positivo' USING ERRCODE='RH001';
  END IF;
  RETURN NULL;
END; $function$

CREATE OR REPLACE FUNCTION public.validar_vinculo_recorrencia()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_TABLE_NAME = 'recorrencias_despesa' THEN
    IF TG_OP = 'UPDATE' AND (NEW.republica_id,NEW.criada_por_id,NEW.inicio,NEW.despesa_origem_id,NEW.chave_idempotencia,NEW.hash_requisicao)
      IS DISTINCT FROM (OLD.republica_id,OLD.criada_por_id,OLD.inicio,OLD.despesa_origem_id,OLD.chave_idempotencia,OLD.hash_requisicao) THEN
      RAISE EXCEPTION 'A identidade da recorrência é permanente' USING ERRCODE='RH001';
    END IF;
    IF NEW.despesa_origem_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM despesas d WHERE d.id=NEW.despesa_origem_id AND d.republica_id=NEW.republica_id) THEN
      RAISE EXCEPTION 'Origem de outra república' USING ERRCODE='RH001';
    END IF;
  ELSIF TG_TABLE_NAME = 'recorrencias_participantes' THEN
    IF NOT EXISTS (SELECT 1 FROM configuracoes_recorrencia c JOIN recorrencias_despesa r ON r.id=c.recorrencia_id
      JOIN membros_republica m ON m.republica_id=r.republica_id JOIN usuarios u ON u.id=m.usuario_id
      WHERE c.id=NEW.configuracao_id AND m.id=NEW.membro_id AND m.ativo AND u.ativo AND u.excluido_em IS NULL) THEN
      RAISE EXCEPTION 'Participante inválido na recorrência' USING ERRCODE='RH001';
    END IF;
    IF EXISTS (SELECT 1 FROM competencias_recorrencia WHERE configuracao_id=NEW.configuracao_id) THEN
      RAISE EXCEPTION 'Configuração utilizada é histórica' USING ERRCODE='RH001';
    END IF;
  ELSE
    IF TG_OP = 'UPDATE' AND (OLD.estado NOT IN ('PENDENTE_REVISAO','BLOQUEADA') OR NEW.estado <> 'REVISADA'
      OR (NEW.recorrencia_id,NEW.competencia,NEW.configuracao_id,NEW.despesa_id,NEW.snapshot,NEW.motivo)
      IS DISTINCT FROM (OLD.recorrencia_id,OLD.competencia,OLD.configuracao_id,OLD.despesa_id,OLD.snapshot,OLD.motivo)) THEN
      RAISE EXCEPTION 'Competências geradas são históricas' USING ERRCODE='RH001';
    END IF;
    IF NEW.configuracao_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM configuracoes_recorrencia c
      WHERE c.id=NEW.configuracao_id AND c.recorrencia_id=NEW.recorrencia_id AND c.vigencia<=NEW.competencia) THEN
      RAISE EXCEPTION 'Configuração de outra recorrência ou competência' USING ERRCODE='RH001';
    END IF;
    IF NEW.despesa_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM despesas d JOIN recorrencias_despesa r ON r.republica_id=d.republica_id
      WHERE d.id=NEW.despesa_id AND r.id=NEW.recorrencia_id AND date_trunc('month',d.vencimento)::date=NEW.competencia) THEN
      RAISE EXCEPTION 'Despesa de outra república ou competência' USING ERRCODE='RH001';
    END IF;
  END IF;
  RETURN NEW;
END; $function$
